int count = 0;
CGAL::Bbox_3 bbox(
    b.minX(), b.minY(), b.minZ(),
    b.maxX(), b.maxY(), b.maxZ());

using Kernel = typename Tree::Traits::Kernel;
using CGALTriangle = CGAL::Triangle_3<Kernel>;

std::vector<CGALTriangle> tris;
tree.all_intersected_primitives(bbox, std::back_inserter(tris));

for (const CGALTriangle& tr : tris) {
    const CGAL::Point_3<Kernel>& p0 = tr[0];
    const CGAL::Point_3<Kernel>& p1 = tr[1];
    const CGAL::Point_3<Kernel>& p2 = tr[2];

    if (b.isInside(Point3d(p0.x(), p0.y(), p0.z())) &&
        b.isInside(Point3d(p1.x(), p1.y(), p1.z())) &&
        b.isInside(Point3d(p2.x(), p2.y(), p2.z()))) {
        ++count;
    }
}
return count;

